<script lang="ts">
 import {onMount} from 'svelte';
 import {Client,can} from './client.ts';
 import {selectTransportUnits} from './handling.ts';
 import HandlingInspector from './HandlingInspector.svelte';
 import type {TransportHandling} from './inspection.ts';
 type RunStatus={identity:{scopes:string[]};quantum:number;run:{id:string;epoch:string;state:string;granted:number;requested:number;speed:number}};
 type Route={code:string;origin:string;destination:string;journey_seconds:number};
 type Vehicle={code:string;location:string;capacity:number;transfer_id:string|null};
 type Transfer={id:string;route:string;sku:string;quantity:number;status:string;custody:string;vehicle:string|null;origin:string;destination:string;planned_eta:number|null;departed_at:number|null;arrived_at:number|null;received_at:number|null;correlation_id:string};
 type Command={id:string;command:{action:string;reference?:string};status:string;reason:string|null;due_at:number;attempts:number};
 type Snapshot={handling?:TransportHandling;configuration:{routes:Route[]};vehicles:Vehicle[];transfers:Transfer[];commands:Command[];movements:{action:string;simulation_time:number;transfer_id:string;quantity:number;custody:string}[]};
 let {client,status}: {client:Client;status:RunStatus}=$props();
 let snapshot:Snapshot|undefined=$state();let error=$state('');let message=$state('');let busy=$state(false);let route=$state('');let sku=$state('PRODUCT');let quantity=$state(1);let correlation=$state(crypto.randomUUID());let assignments:Record<string,string>=$state({});let retry:ReturnType<Client['transport']>|undefined=$state();
 const writable=$derived(can(status.identity,'jobs:write')&&['running','held'].includes(status.run.state));
 function progress(tr:Transfer){if(tr.departed_at===null||tr.planned_eta===null)return 0;return Math.round(Math.max(0,Math.min(100,100*(status.run.granted-tr.departed_at)/(tr.planned_eta-tr.departed_at))))}
 async function refresh(){try{snapshot=await client.request<Snapshot>('/api/transport');if(!route&&snapshot.configuration.routes.length)route=snapshot.configuration.routes[0].code}catch(e){error=e instanceof Error?e.message:String(e)}}
 function pending(id:string){return snapshot?.commands.some(c=>c.status==='pending'&&(c.id===id||c.command.reference===id))??false}
 async function send(action:string,fields:Record<string,unknown>){if(busy||retry)return;busy=true;error='';message='';try{
  const current=await client.request<RunStatus>('/api/status');if(current.run.id!==status.run.id||current.run.epoch!==status.run.epoch)throw new Error('The run changed. Refresh before issuing another command.');
  retry=client.transport({run_id:current.run.id,epoch:current.run.epoch,due_at:Math.max(current.run.granted,current.run.requested)+2*current.quantum+current.run.speed,action,...fields});await deliver()
 }catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
 async function deliver(){if(!retry)return;try{const saved=await retry.send();retry=undefined;message=`Command accepted: ${saved.id}`;await refresh()}catch(e){error=e instanceof Error?e.message:String(e)}}
 async function retryCommand(){busy=true;error='';await deliver();busy=false}
 function request(event:SubmitEvent){event.preventDefault();try{if(!snapshot?.handling)throw new Error('Handling-unit data is unavailable. Refresh before requesting transport.');const origin=snapshot.configuration.routes.find(r=>r.code===route)?.origin??'';const unit_ids=selectTransportUnits(snapshot.handling.units,snapshot.handling.unit_context,sku,quantity,origin);void send('request',{route,sku,quantity,correlation_id:correlation,unit_ids});correlation=crypto.randomUUID()}catch(e){error=e instanceof Error?e.message:String(e)}}
 onMount(()=>{void refresh();const timer=setInterval(refresh,750);return()=>clearInterval(timer)});
</script>
{#if error}<div class="notice" role="alert">{error}</div>{/if}
{#if retry}<section><h2>Command awaiting confirmation</h2><p>The saved command retains its original fields and idempotency key.</p><div class="actions"><button onclick={retryCommand} disabled={busy}>Retry same transport command</button><button onclick={()=>{retry=undefined;error=''}}>New transport command</button></div></section>{/if}
{#if message}<p role="status" class="identifier">{message}</p>{/if}
{#if snapshot}
 <div class="columns"><section data-fleet><div class="section-title"><h2>Fleet availability</h2><span>{snapshot.vehicles.length} vehicles</span></div><div class="table-wrap"><table><thead><tr><th>Vehicle</th><th>Location</th><th>Capacity</th><th>Availability</th></tr></thead><tbody>{#each snapshot.vehicles as vehicle}<tr><td>{vehicle.code}</td><td>{vehicle.location}</td><td>{vehicle.capacity} items</td><td>{vehicle.transfer_id?'Reserved':'Available'}</td></tr>{/each}</tbody></table></div><h2 class="route-title">Routes</h2><div class="table-wrap"><table><thead><tr><th>Route</th><th>From / to</th><th>Journey</th></tr></thead><tbody>{#each snapshot.configuration.routes as r}<tr><td>{r.code}</td><td>{r.origin} / {r.destination}</td><td>{r.journey_seconds} s</td></tr>{/each}</tbody></table></div></section>
 {#if writable}<section><h2>Request transport</h2><p>Request exact whole units already in Logistics custody. Units are never split.</p><form onsubmit={request}><label>Route<select bind:value={route} required>{#each snapshot.configuration.routes as r}<option value={r.code}>{r.code}</option>{/each}</select></label><label>SKU<input bind:value={sku} pattern={'[A-Z0-9][A-Z0-9_-]{0,31}'} maxlength="32" required /></label><label>Load quantity<input type="number" min="1" max="10000" step="1" bind:value={quantity} required /></label><label>Correlation ID<input bind:value={correlation} required /></label><button class="primary" disabled={busy||!!retry}>Request transport</button></form></section>{/if}</div>
 {#key status.run.id+':'+status.run.epoch}<HandlingInspector handling={snapshot.handling} />{/key}
 <section data-transfers><div class="section-title"><h2>Transport queue</h2><span>{snapshot.transfers.length} transfers</span></div><p>ETA is planned simulation time. Arrival confirms the journey; receipt confirms the destination accepted the goods.</p><div class="table-wrap"><table><thead><tr><th>Transfer / route</th><th>Load</th><th>Status / custody</th><th>Vehicle</th><th>Planned ETA / arrived / received (s)</th><th>Actions</th></tr></thead><tbody>{#each snapshot.transfers as tr}<tr><td><span class="identifier">{tr.id}</span><br>{tr.route}<br><span class="identifier">{tr.correlation_id}</span></td><td>{tr.quantity} {tr.sku}</td><td>{tr.status}<br><span class="identifier">{tr.custody}</span></td><td>{tr.vehicle??'Unassigned'}</td><td>{tr.planned_eta??'—'} / {tr.arrived_at??'—'} / {tr.received_at??'—'}{#if tr.departed_at!==null}<br><span class="identifier">Estimated progress: {progress(tr)}%</span>{/if}</td><td>{#if writable&&!pending(tr.id)}<div class="actions">{#if tr.status==='requested'}<select aria-label="Assign vehicle" value={assignments[tr.id]??''} onchange={e=>{assignments[tr.id]=e.currentTarget.value}}><option value="">Select vehicle</option>{#each snapshot.vehicles.filter(v=>!v.transfer_id&&v.location===tr.origin&&v.capacity>=tr.quantity) as v}<option value={v.code}>{v.code} ({v.capacity} items)</option>{/each}</select><button onclick={()=>send('assign',{reference:tr.id,vehicle:assignments[tr.id]})} disabled={busy||!!retry||!assignments[tr.id]}>Assign</button>{:else if tr.status==='assigned'}<button onclick={()=>send('load',{reference:tr.id})} disabled={busy||!!retry}>Load</button>{:else if tr.status==='loaded'}<button onclick={()=>send('depart',{reference:tr.id})} disabled={busy||!!retry}>Depart</button>{:else if tr.status==='in_transit'&&tr.planned_eta!==null&&status.run.granted>=tr.planned_eta}<button onclick={()=>send('arrive',{reference:tr.id})} disabled={busy||!!retry}>Confirm arrival</button>{:else if tr.status==='arrived'}<button onclick={()=>send('unload',{reference:tr.id})} disabled={busy||!!retry}>Unload</button>{:else if tr.status==='unloaded'}<button onclick={()=>send('receive',{reference:tr.id})} disabled={busy||!!retry}>Confirm receipt</button>{/if}</div>{:else if pending(tr.id)}Command pending{/if}</td></tr>{:else}<tr><td colspan="6">No transport requested in this run.</td></tr>{/each}</tbody></table></div></section>
 <section><h2>Transport commands</h2><div class="table-wrap"><table><thead><tr><th>Command</th><th>Due (s)</th><th>Action</th><th>Outcome</th><th>Reason</th></tr></thead><tbody>{#each snapshot.commands as command}<tr><td class="identifier">{command.id}</td><td>{command.due_at}</td><td>{command.command.action}</td><td>{command.status}</td><td>{command.reason??'—'}</td></tr>{:else}<tr><td colspan="5">No transport commands.</td></tr>{/each}</tbody></table></div></section>
 <section><h2>Custody history</h2><div class="table-wrap"><table><thead><tr><th>Time (s)</th><th>Transfer</th><th>Action</th><th>Quantity</th><th>Custody</th></tr></thead><tbody>{#each snapshot.movements as movement}<tr><td>{movement.simulation_time}</td><td class="identifier">{movement.transfer_id}</td><td>{movement.action}</td><td>{movement.quantity}</td><td>{movement.custody}</td></tr>{:else}<tr><td colspan="5">No custody movements.</td></tr>{/each}</tbody></table></div></section>
{/if}
